def P(n):
    """Calculates P(n) = n^3 + 4n^2 + 6n + 4."""
    return n**3 + 4*n**2 + 6*n + 4

def has_only_factors_2_and_5(num):
    """Checks if a number is only divisible by 2 and 5."""
    if num == 0:
        # 0 is technically divisible by everything, but since P(n) for n>=0 is >= 4, this is a safety check.
        # P(0) = 4, so num will be positive.
        return False 

    # Repeatedly divide by 2 and 5
    while num % 2 == 0:
        num //= 2
    while num % 5 == 0:
        num //= 5

    # If the remaining number is 1, it only had factors 2 and 5.
    return num == 1

solutions = []
for n in range(11): # Test n from 0 to 10
    p_n = P(n)
    if has_only_factors_2_and_5(p_n):
        solutions.append((n, p_n))

print("--- Results ---")
if solutions:
    print("Found solutions (n, P(n)):")
    for n, p_n in solutions:
        print(f"n = {n}, P(n) = {p_n}")
else:
    print("No solutions found in the range n=0 to n=10.")

def is_smooth_2_5(N):
    """Checks if all prime factors of N are 2 or 5."""
    if N <= 0:
        return False

    # Divide out factors of 2
    while N % 2 == 0:
        N //= 2

    # Divide out factors of 5
    while N % 5 == 0:
        N //= 5

    # If N is reduced to 1, all prime factors were 2 or 5
    return N == 1

